@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Unbounded:wght@500;600;700&display=swap');
:root{--ink:#10131e;--panel:#171b28;--panel2:#1d2231;--line:#303548;--muted:#9297a8;--gold:#e4b85d;--gold2:#f3d48f;--cream:#f1eee8;--red:#da6873;--blue:#77dce0}*{box-sizing:border-box}html,body{margin:0;width:100%;min-height:100%;background:#0d1018;color:var(--cream);font-family:'DM Sans',sans-serif}body{min-height:100svh;background:radial-gradient(ellipse at 50% 50%,#202231 0,#12151f 55%,#0d1018 100%);overflow-x:hidden}.game-shell{max-width:1510px;margin:auto;padding:21px 38px 13px;min-height:100svh;display:flex;flex-direction:column}.topbar{height:61px;display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;border-bottom:1px solid #282c3a;padding-bottom:14px}.brand{display:flex;align-items:center;gap:11px;color:var(--cream);text-decoration:none;font:600 10px/1.35 'Unbounded',sans-serif;letter-spacing:1.6px}.brand b{color:var(--gold);font-weight:600}.brand-mark{width:34px;height:34px;display:grid;place-items:center;border:1px solid #6b5733;border-radius:50%;font-size:20px;color:var(--gold)}.top-center{text-align:center;display:flex;flex-direction:column;gap:4px}.eyebrow,.panel-kicker,.mini-label,.tiny-label,.modal-eyebrow{font:500 9px 'DM Mono',monospace;letter-spacing:2px;color:#8f93a3}.seed{font:10px 'DM Mono',monospace;letter-spacing:1.4px;color:#d4d0c8}.seed:first-letter{color:#74d7b4}.icon-btn{justify-self:end;width:35px;height:35px;background:#1b1e2b;color:var(--gold);border:1px solid #343747;border-radius:50%;font-size:16px;cursor:pointer}.icon-btn.muted{color:#777}.game-layout{display:grid;grid-template-columns:181px minmax(0,1fr) 181px;gap:19px;align-items:stretch;flex:1;padding:20px 0 17px;min-height:580px}.side-panel{background:linear-gradient(155deg,#191d2a,#151823);border:1px solid #2c3040;border-radius:4px;padding:21px 17px;position:relative;overflow:hidden}.panel-kicker{padding-bottom:18px;border-bottom:1px solid #303344}.stat-block{display:flex;gap:12px;align-items:center;padding:19px 0 13px}.stat-icon{display:grid;place-items:center;border:1px solid #5b4b30;width:36px;height:36px;border-radius:50%;font-size:16px}.gold{color:var(--gold)}.stat-block small,.stat-block strong{display:block}.stat-block small{font:9px 'DM Mono',monospace;color:#898e9f;letter-spacing:.8px}.stat-block strong{font:19px 'Unbounded',sans-serif;color:var(--gold2);margin-top:5px}.divider{height:1px;background:#303344}.side-copy{padding-top:19px}.mini-label{font-size:8px;letter-spacing:1.5px}.side-copy p{font-size:12px;color:#c0c1c6;line-height:1.7;margin:8px 0 0}.best-run{position:absolute;bottom:115px;left:17px;display:flex;flex-direction:column;gap:7px}.best-run strong{font:20px 'Unbounded',sans-serif;color:#efeee9}.record-caption{font-size:10px;color:#848999}.sigil-art{position:absolute;bottom:-28px;right:-11px;width:130px;height:130px;border:1px solid #393446;border-radius:50%;color:#645335;display:grid;place-items:center;font-size:44px;opacity:.65}.sigil-art:before,.sigil-art:after{content:'';position:absolute;inset:12px;border:1px solid #443e3d;border-radius:50%}.sigil-art:after{inset:26px;transform:rotate(45deg);border-radius:8px}.sigil-art i,.sigil-art b{position:absolute;font-style:normal;font-size:15px}.sigil-art i{left:16px;top:31px}.sigil-art b{right:18px;bottom:28px}.arena-wrap{min-width:0;display:flex;flex-direction:column}.arena-top,.arena-footer{height:35px;background:#1a1e2b;border:1px solid #303446;display:flex;justify-content:space-between;align-items:center;padding:0 12px;font:9px 'DM Mono',monospace;letter-spacing:1px;color:#a6a8b0}.arena-top{border-radius:4px 4px 0 0;border-bottom:0}.map-name{color:#e2dfd8}.map-dot{display:inline-block;width:6px;height:6px;background:#82d8b8;border-radius:50%;margin-right:7px;box-shadow:0 0 8px #82d8b8}.run-tag{color:#a7a4aa}.arena{position:relative;flex:1;min-height:470px;overflow:hidden;background:#151927;border-left:1px solid #303446;border-right:1px solid #303446}.arena canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.arena-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 35%,rgba(5,8,15,.36) 100%);z-index:1}.start-screen{position:absolute;inset:0;z-index:2;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;background:radial-gradient(ellipse at 50% 48%,rgba(19,22,34,.18),rgba(12,14,24,.7))}.moon{position:absolute;width:270px;height:270px;left:50%;top:47%;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(circle,#d2b776 0,#b09359 30%,rgba(147,114,64,.2) 60%,transparent 72%);opacity:.12;filter:blur(1px)}.pretitle{font:9px 'DM Mono',monospace;color:#d6b66e;letter-spacing:2.5px;display:flex;align-items:center;gap:10px;margin-bottom:19px}.pretitle i{display:block;width:19px;height:1px;background:#927641}.start-screen h1,.modal-card h2{font:600 clamp(28px,4vw,47px)/1.13 'Unbounded',sans-serif;letter-spacing:-2px;margin:0;color:#f5f0e5;text-shadow:0 4px 20px #000}.start-screen h1 em,.modal-card h2 em{font-style:normal;color:var(--gold)}.start-screen>p{font-size:12px;line-height:1.7;color:#b1b2bc;margin:17px 0 22px}.primary-btn{height:48px;min-width:224px;border:1px solid #f0ce84;background:linear-gradient(110deg,#dfb55f,#c79543);color:#171722;padding:0 18px;display:flex;align-items:center;justify-content:space-between;gap:28px;font:700 10px 'DM Mono',monospace;letter-spacing:1.3px;cursor:pointer;box-shadow:0 6px 25px #cf9f473b;transition:.18s transform,.18s filter}.primary-btn b{font-size:18px}.primary-btn:hover{transform:translateY(-2px);filter:brightness(1.12)}.controls-hint{margin-top:23px;display:flex;align-items:center;gap:4px}.keycap{display:inline-grid;place-items:center;width:20px;height:20px;border:1px solid #474958;background:#202330;border-radius:3px;color:#c9c8c2;font:9px 'DM Mono',monospace}.hint-text{font:8px 'DM Mono',monospace;color:#9698a3;letter-spacing:.7px;margin-left:5px}.hint-sep{color:#646878;margin:0 4px}.arena-footer{height:30px;border-top:0;border-radius:0 0 4px 4px;color:#8f94a4;font-size:8px}.arena-footer span:first-child{display:flex;align-items:center;gap:7px}.pulse-dot{width:5px;height:5px;border-radius:50%;background:#87d8b7;box-shadow:0 0 7px #87d8b7}.arena-footer b{color:var(--gold)}.right-panel{padding:21px 16px}.character-card{text-align:center}.portrait-frame{width:105px;height:111px;margin:20px auto 12px;position:relative;display:grid;place-items:center;clip-path:polygon(50% 0,92% 18%,92% 70%,50% 100%,8% 70%,8% 18%);background:linear-gradient(145deg,#665336,#2d2930);}.portrait-frame:after{content:'';position:absolute;inset:4px;clip-path:inherit;background:radial-gradient(circle at 50% 34%,#b8955b 0,#423344 42%,#181c2a 76%)}.portrait-halo{position:absolute;z-index:1;top:20px;width:59px;height:59px;border:1px solid #d3b06b;border-radius:50%;box-shadow:0 0 22px #d8af5733}.portrait{z-index:2;color:#292333;font-size:77px;line-height:1;transform:translateY(13px);text-shadow:0 2px #d3b273}.portrait-star{position:absolute;z-index:3;top:21px;right:24px;color:#f0d484;font-size:12px}.character-name{font:600 15px/1.4 'Unbounded',sans-serif;letter-spacing:1px}.character-name em{font-style:normal;color:var(--gold);font-size:12px}.character-sub{font:8px 'DM Mono',monospace;letter-spacing:.6px;color:#9899a4;margin-top:8px}.character-rule{height:1px;background:#353747;margin:17px 0 13px}.trait{display:flex;align-items:flex-start;text-align:left;gap:8px}.trait-icon{color:#e2bd70;font-size:17px}.trait p{font-size:10px;line-height:1.5;color:#a6a8b3;margin:0}.trait b{font:8px 'DM Mono',monospace;color:#d0c2a0;letter-spacing:.7px}.side-bottom{position:absolute;bottom:18px;left:16px;right:16px}.control-row{display:flex;gap:3px;align-items:center;margin-top:9px}.control-row small{font:8px 'DM Mono',monospace;color:#9296a4;margin-left:6px;letter-spacing:.8px}.keycap.wide{width:35px}.mobile-note{display:none;font-size:9px;color:#8e92a1}.hud{position:absolute;z-index:3;inset:0;pointer-events:none;display:none}.hud.visible{display:block}.hud-topline{position:absolute;top:16px;left:16px;right:16px;display:flex;align-items:center;gap:12px}.timer-box{display:flex;flex-direction:column;gap:3px}.tiny-label{font-size:8px;color:#a9a9b0}.timer-box strong{font:600 21px 'Unbounded',sans-serif;color:#f3eee1;text-shadow:0 2px 6px #000}.wave-box{display:flex;align-items:center;gap:7px;margin-left:9px}.wave-symbol{color:#e4bd70;font-size:20px}.wave-box small,.wave-box b{display:block}.wave-box small{font:7px 'DM Mono',monospace;color:#a5a6ae;letter-spacing:1px}.wave-box b{font:12px 'Unbounded',sans-serif;color:#e3c47e;margin-top:2px}.pause-btn{pointer-events:auto;margin-left:auto;border:1px solid #ffffff3b;background:#141723b8;color:#f0e3c7;width:33px;height:33px;border-radius:3px;font-size:14px;cursor:pointer}.health-wrap,.xp-wrap{position:absolute;left:16px;right:16px}.health-wrap{top:69px}.xp-wrap{top:96px}.health-meta,.xp-meta{display:flex;justify-content:space-between;color:#f2d5d4;font:8px 'DM Mono',monospace;letter-spacing:.7px;margin-bottom:4px;text-shadow:0 1px 3px #000}.health-meta b,.xp-meta b{font-weight:500}.health-meta span:last-child,.xp-meta span:last-child{color:#d8d6d3}.bar{height:5px;border:1px solid #e8e4df38;background:#10121bbc;border-radius:5px;overflow:hidden}.bar i{display:block;height:100%;width:100%;transition:width .2s;border-radius:5px}.health-bar i{background:linear-gradient(90deg,#c74457,#f17d78);box-shadow:0 0 8px #d53b55}.xp-bar i{background:linear-gradient(90deg,#55b7ad,#b9db83);box-shadow:0 0 7px #68c3b4}.xp-meta{color:#d4e5cf}.kill-counter{position:absolute;right:16px;top:124px;display:flex;align-items:center;gap:8px;background:#10131ab8;padding:6px 9px;border:1px solid #fff2;border-radius:3px}.skull{font-size:18px;color:#efb962}.kill-counter b,.kill-counter small{display:block}.kill-counter b{font:11px 'Unbounded',sans-serif}.kill-counter small{font:6px 'DM Mono',monospace;color:#aaa;margin-top:3px;letter-spacing:.8px}.weapon-slots{position:absolute;bottom:13px;left:14px;display:flex;gap:5px}.weapon-slot{width:31px;height:31px;border:1px solid #e2c57d88;background:#171924c9;color:#f5d47d;display:grid;place-items:center;font-size:15px;position:relative;border-radius:3px}.weapon-slot small{position:absolute;bottom:1px;right:3px;font:7px 'DM Mono',monospace;color:#eee}.empty-slot{color:#858897;border-color:#fff3}.overlay{position:absolute;z-index:5;inset:0;display:none;align-items:center;justify-content:center;background:#090c16bf;backdrop-filter:blur(5px);padding:14px}.overlay.show{display:flex}.modal-card{width:min(560px,96%);padding:25px 24px;background:linear-gradient(145deg,#202434,#171a26);border:1px solid #555044;box-shadow:0 15px 70px #0009;text-align:center}.modal-eyebrow{display:block;color:#dfbd72;margin-bottom:10px;font-size:8px}.modal-card h2{font-size:27px;letter-spacing:-1px}.modal-card>p{font-size:11px;color:#afb1ba;margin:9px 0 20px}.upgrade-choices{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.upgrade-choice{min-height:131px;padding:14px 10px 12px;background:#252a3b;border:1px solid #414659;color:#eee;text-align:left;cursor:pointer;transition:.15s}.upgrade-choice:hover{border-color:#e1bd6e;background:#303448;transform:translateY(-2px)}.upgrade-icon{font-size:24px;color:#efc76f}.upgrade-choice h3{font:600 10px 'Unbounded',sans-serif;margin:8px 0;color:#f2dfb6}.upgrade-choice p{font-size:9px;line-height:1.5;color:#b0b3bd;margin:0}.small-modal{width:min(380px,96%);padding:30px}.small-modal h2{font-size:32px}.small-modal .primary-btn{margin:20px auto 0}.run-results{display:flex;justify-content:center;gap:24px;margin:20px 0 5px;padding:13px 0;border-top:1px solid #3a3d4c;border-bottom:1px solid #3a3d4c}.run-results span{display:flex;flex-direction:column;gap:6px}.run-results small{font:7px 'DM Mono',monospace;color:#999;letter-spacing:1px}.run-results b{font:15px 'Unbounded',sans-serif;color:var(--gold2)}.touch-controls{display:none;position:absolute;z-index:4;bottom:15px;right:17px;align-items:center;flex-direction:column;gap:4px;touch-action:none}.joystick{width:96px;height:96px;position:relative;touch-action:none}.joy-ring{position:absolute;inset:0;border:1px solid #ffffff55;background:#171b2b88;border-radius:50%;box-shadow:inset 0 0 20px #0008}.joy-knob{position:absolute;width:38px;height:38px;top:29px;left:29px;border:1px solid #e7c779;background:#d4ad61cc;border-radius:50%;box-shadow:0 2px 12px #0008;pointer-events:none}.touch-tip{font:7px 'DM Mono',monospace;letter-spacing:1px;color:#e0d6bd;text-shadow:0 1px 3px #000}.toast{position:absolute;z-index:6;left:50%;top:35%;transform:translate(-50%,-50%);padding:9px 15px;background:#191d2b;border:1px solid #d7b668;color:#eed89b;font:9px 'DM Mono',monospace;letter-spacing:1px;opacity:0;pointer-events:none;transition:opacity .2s}.toast.show{opacity:1}.page-footer{height:23px;display:flex;justify-content:space-between;align-items:center;border-top:1px solid #282c3a;color:#787d8d;font:8px 'DM Mono',monospace;letter-spacing:1px}.page-footer b{color:var(--gold)}
@media(max-width:980px){.game-shell{padding:16px 18px 10px}.game-layout{grid-template-columns:145px minmax(0,1fr) 145px;gap:12px}.side-panel{padding:17px 12px}.right-panel{padding:17px 11px}.best-run{left:12px}.side-bottom{left:11px;right:11px}.arena{min-height:420px}.character-sub{font-size:7px}.portrait-frame{width:90px;height:96px}}
@media(max-width:720px){body{background:#10131e}.game-shell{padding:0 0 env(safe-area-inset-bottom);min-height:100svh}.topbar{height:54px;padding:0 15px 0;border-bottom:1px solid #282c3a;grid-template-columns:1fr 1fr 36px}.brand{font-size:9px}.brand-mark{width:29px;height:29px;font-size:17px}.top-center{align-items:flex-end;text-align:right}.eyebrow{font-size:7px;letter-spacing:1.3px}.seed{font-size:8px}.icon-btn{width:31px;height:31px}.game-layout{display:block;padding:0;min-height:0;flex:1}.left-panel,.right-panel{display:none}.arena-wrap{height:calc(100svh - 83px);min-height:490px}.arena-top{height:29px;border-radius:0;padding:0 10px;font-size:8px}.arena{min-height:0;height:calc(100% - 55px);border-left:0;border-right:0}.arena-footer{height:26px;border-radius:0;font-size:7px;padding:0 9px}.start-screen{padding:0 15px}.moon{width:240px;height:240px}.pretitle{font-size:8px;margin-bottom:16px}.start-screen h1{font-size:clamp(29px,9vw,43px)}.start-screen>p{font-size:11px;margin:14px 0 20px}.controls-hint{margin-top:20px;flex-wrap:wrap;justify-content:center}.hint-text{font-size:7px}.hud-topline{top:11px;left:12px;right:12px}.timer-box strong{font-size:18px}.health-wrap,.xp-wrap{left:12px;right:12px}.health-wrap{top:59px}.xp-wrap{top:85px}.kill-counter{top:115px;right:12px}.weapon-slots{bottom:12px;left:10px}.touch-controls{display:flex;bottom:14px;right:14px}.touch-controls.hidden{display:none}.overlay{padding:10px}.modal-card{padding:22px 15px}.modal-card h2{font-size:24px}.upgrade-choices{gap:6px}.upgrade-choice{min-height:128px;padding:11px 8px}.upgrade-choice h3{font-size:8px}.upgrade-choice p{font-size:8px}.upgrade-icon{font-size:21px}.small-modal{padding:27px 19px}.page-footer{display:none}}
@media(max-height:620px) and (max-width:720px){.arena-wrap{height:calc(100svh - 69px);min-height:0}.start-screen h1{font-size:30px}.start-screen>p{margin:10px 0 12px}.controls-hint{margin-top:12px}.primary-btn{height:42px}}

(() => {
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const arena = document.getElementById('arena');
  const el = (id) => document.getElementById(id);
  const ui = {
    start:el('startScreen'), hud:el('hud'), level:el('levelOverlay'), pause:el('pauseOverlay'), end:el('endOverlay'),
    timer:el('timer'), wave:el('wave'), levelText:el('level'), xpText:el('xpText'), xpFill:el('xpFill'),
    healthText:el('healthText'), healthFill:el('healthFill'), kills:el('kills'), slots:el('weaponSlots'),
    status:el('statusText'), toast:el('toast'), touch:el('touchControls'), joystick:el('joystick'), knob:el('joyKnob')
  };
  const TAU = Math.PI * 2;
  let W=800,H=500,dpr=1,raf=0,last=0,mode='menu',muted=true,audioCtx=null;
  let player,enemies=[],orbs=[],shots=[],particles=[],decor=[],elapsed=0,kills=0,gold=0,spawnClock=0,attackClock=0,damageClock=0,fireClock=0,chestClock=0,gameGold=0,level=1,xp=0,nextXp=12,weaponLevel=1,extraSlots=0;
  let keys={},joy={x:0,y:0,active:false},toastTimer=0,animTime=0;
  let best=Number(localStorage.getItem('lastDawnBest')||0),bank=Number(localStorage.getItem('lastDawnGold')||0);
  const upgrades=[
    {icon:'✦',name:'FUEGO AZUL',desc:'Aumenta el daño de tu proyectil mágico.',type:'weapon'},
    {icon:'☽',name:'PASO LIGERO',desc:'Muévete un 12% más rápido.',type:'speed'},
    {icon:'✧',name:'CORAZÓN DE ROBLE',desc:'Recupera vida y aumenta tu vitalidad máxima.',type:'health'},
    {icon:'❋',name:'IMÁN DE LUZ',desc:'Atrae gemas desde más lejos.',type:'magnet'},
    {icon:'➶',name:'FUEGO VELOZ',desc:'Lanza proyectiles con más frecuencia.',type:'rate'},
    {icon:'◇',name:'SOMBRA GEMELA',desc:'Añade un proyectil extra a tu arsenal.',type:'extra'}
  ];
  function resize(){const r=arena.getBoundingClientRect();W=Math.max(1,r.width);H=Math.max(1,r.height);dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);seedDecor();}
  function seedDecor(){decor=[];for(let i=0;i<95;i++)decor.push({x:Math.random()*W,y:Math.random()*H,r:Math.random()*1.7+.3,a:Math.random()*.32+.06,p:Math.random()*TAU});}
  window.addEventListener('resize',resize); resize();
  function makePlayer(){return{x:0,y:0,r:11,hp:100,maxHp:100,speed:178,magnet:40,face:1,invuln:0};}
  function begin(){elapsed=0;kills=0;gameGold=0;level=1;xp=0;nextXp=12;weaponLevel=1;extraSlots=0;enemies=[];orbs=[];shots=[];particles=[];spawnClock=.5;attackClock=.4;damageClock=0;fireClock=0;chestClock=42;player=makePlayer();mode='playing';ui.start.style.display='none';ui.hud.classList.add('visible');ui.level.classList.remove('show');ui.pause.classList.remove('show');ui.end.classList.remove('show');ui.touch.classList.remove('hidden');ui.status.textContent='LA NOCHE HA COMENZADO';document.getElementById('runTag').textContent='NOCHE 01  ·  DIFICULTAD I';updateUI();last=performance.now();cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);}
  function randomUpgrade(){let picks=[];while(picks.length<3){const u=upgrades[Math.floor(Math.random()*upgrades.length)];if(!picks.includes(u))picks.push(u);}return picks;}
  function showLevelUp(){mode='level';ui.level.classList.add('show');ui.level.setAttribute('aria-hidden','false');const box=el('upgradeChoices');box.innerHTML='';for(const u of randomUpgrade()){const b=document.createElement('button');b.className='upgrade-choice';b.innerHTML=`<div class="upgrade-icon">${u.icon}</div><h3>${u.name}</h3><p>${u.desc}</p>`;b.onclick=()=>applyUpgrade(u);box.appendChild(b);}playTone(540,.11);}
  function applyUpgrade(u){if(u.type==='weapon')weaponLevel=Math.min(8,weaponLevel+1);if(u.type==='speed')player.speed*=1.12;if(u.type==='health'){player.maxHp+=20;player.hp=Math.min(player.maxHp,player.hp+35);}if(u.type==='magnet')player.magnet+=34;if(u.type==='rate')attackClock=Math.max(0,attackClock-.25);if(u.type==='extra')extraSlots=Math.min(3,extraSlots+1);mode='playing';ui.level.classList.remove('show');ui.level.setAttribute('aria-hidden','true');showToast(u.name+' MEJORADO');updateUI();last=performance.now();raf=requestAnimationFrame(loop);}
  function togglePause(){if(mode==='playing'){mode='paused';ui.pause.classList.add('show');ui.touch.classList.add('hidden');ui.status.textContent='PARTIDA EN PAUSA';}else if(mode==='paused'){mode='playing';ui.pause.classList.remove('show');ui.touch.classList.remove('hidden');ui.status.textContent='LA NOCHE HA COMENZADO';last=performance.now();raf=requestAnimationFrame(loop);}}
  function finish(victory=false){mode='ended';ui.touch.classList.add('hidden');ui.hud.classList.remove('visible');ui.end.classList.add('show');el('endEyebrow').textContent=victory?'EL SOL HA VENCIDO A LAS SOMBRAS':'EL BOSQUE TE RECUERDA';el('endTitle').innerHTML=victory?'HAS VISTO EL<br><em>AMANECER</em>':'LA NOCHE<br><em>TERMINA</em>';el('endText').textContent=victory?'Resististe hasta el alba. Pero siempre hay otra noche.':'Cada final es el comienzo de otra leyenda.';el('resultTime').textContent=formatTime(elapsed);el('resultKills').textContent=kills;el('resultGold').textContent=gameGold;bank+=gameGold;localStorage.setItem('lastDawnGold',bank);if(elapsed>best){best=elapsed;localStorage.setItem('lastDawnBest',best);}el('bankGold').textContent=String(bank).padStart(3,'0');el('bestTime').textContent=formatTime(best);ui.status.textContent='PARTIDA FINALIZADA';playTone(victory?700:150,.35);}
  function formatTime(s){const n=Math.floor(s);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
  function updateUI(){if(!player)return;ui.timer.textContent=formatTime(elapsed);ui.wave.textContent=String(Math.floor(elapsed/30)+1).padStart(2,'0');ui.levelText.textContent=String(level).padStart(2,'0');ui.xpText.textContent=`${Math.floor(xp)} / ${nextXp} XP`;ui.xpFill.style.width=Math.min(100,xp/nextXp*100)+'%';ui.healthText.textContent=`${Math.max(0,Math.ceil(player.hp))} / ${player.maxHp}`;ui.healthFill.style.width=Math.max(0,player.hp/player.maxHp*100)+'%';ui.kills.textContent=kills;let slots=`<div class="weapon-slot active-slot">✦<small>${weaponLevel}</small></div>`;for(let i=0;i<Math.min(extraSlots,2);i++)slots+=`<div class="weapon-slot">❋<small>1</small></div>`;for(let i=extraSlots;i<2;i++)slots+='<div class="weapon-slot empty-slot">＋</div>';ui.slots.innerHTML=slots;}
  function showToast(s){ui.toast.textContent=s;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1350);}
  function playTone(freq,duration){if(muted)return;try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(e){}}
  function spawnEnemy(){const ang=Math.random()*TAU,margin=35,d=Math.max(W,H)*.65+margin;const x=player.x+Math.cos(ang)*d,y=player.y+Math.sin(ang)*d;const t=Math.random();let e;if(elapsed>45&&t<.22)e={kind:'brute',r:15,hp:5+elapsed*.08,speed:34+Math.random()*10,damage:18,color:'#8b547c',value:3};else if(t<.38)e={kind:'runner',r:7,hp:1+elapsed*.017,speed:69+Math.random()*20,damage:8,color:'#d07972',value:1};else e={kind:'shade',r:10,hp:2+elapsed*.025,speed:43+Math.random()*17,damage:10,color:'#a96877',value:1};e.x=x;e.y=y;e.hit=0;e.wobble=Math.random()*TAU;enemies.push(e);}
  function nearest(){let target=null,d=Infinity;for(const e of enemies){const q=(e.x-player.x)**2+(e.y-player.y)**2;if(q<d){d=q;target=e;}}return target;}
  function fire(){const target=nearest();if(!target)return;const n=1+Math.min(extraSlots,2);for(let i=0;i<n;i++){let dx=target.x-player.x,dy=target.y-player.y,a=Math.atan2(dy,dx)+(i-(n-1)/2)*.13;shots.push({x:player.x+Math.cos(a)*13,y:player.y+Math.sin(a)*13,vx:Math.cos(a)*390,vy:Math.sin(a)*390,life:1.35,damage:1.55+weaponLevel*.8,r:4+weaponLevel*.25});}player.face=target.x>player.x?1:-1;playTone(280+weaponLevel*28,.045);}
  function addOrb(x,y,val=1){orbs.push({x,y,v:val,r:val>2?5:3.5,p:Math.random()*TAU});}
  function burst(x,y,color,n=7){for(let i=0;i<n;i++){const a=Math.random()*TAU,s=20+Math.random()*90;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.5,max:.75,color,r:1+Math.random()*2});}}
  function damagePlayer(amount){if(player.invuln>0)return;player.hp-=amount;player.invuln=.55;damageClock=0;burst(player.x,player.y,'#f77c81',8);playTone(110,.11);if(player.hp<=0)finish(false);}
  function gainXp(value){xp+=value;while(xp>=nextXp&&mode==='playing'){xp-=nextXp;level++;nextXp=Math.floor(nextXp*1.25+4);updateUI();showLevelUp();break;}}
  function loop(now){if(mode!=='playing')return;const dt=Math.min(.04,(now-last)/1000||0);last=now;animTime+=dt;elapsed+=dt;update(dt);render();updateUI();if(elapsed>=180){finish(true);return;}raf=requestAnimationFrame(loop);}
  function update(dt){let mx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),my=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);mx+=joy.x;my+=joy.y;const mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag;}player.x+=mx*player.speed*dt;player.y+=my*player.speed*dt;if(mx)player.face=mx>0?1:-1;player.invuln=Math.max(0,player.invuln-dt);spawnClock-=dt;attackClock-=dt;fireClock-=dt;damageClock-=dt;chestClock-=dt;
    if(spawnClock<=0){spawnEnemy();spawnClock=Math.max(.12,.78-elapsed*.002)+Math.random()*.24;}
    if(attackClock<=0){fire();attackClock=Math.max(.31,1.05-(weaponLevel-1)*.075);}
    if(fireClock<=0){const nearestE=nearest();if(nearestE&&Math.hypot(nearestE.x-player.x,nearestE.y-player.y)<150){const a=Math.atan2(nearestE.y-player.y,nearestE.x-player.x);for(let i=0;i<9;i++)particles.push({x:player.x+Math.cos(i*TAU/9+animTime)*20,y:player.y+Math.sin(i*TAU/9+animTime)*20,vx:0,vy:0,life:.34,max:.34,color:'#75d7dc',r:2.5});for(const e of enemies){if(Math.hypot(e.x-player.x,e.y-player.y)<40){e.hp-=3;}}}fireClock=7;}
    for(const e of enemies){const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;e.wobble+=dt*4;if(d<e.r+player.r+1){damageClock-=dt;if(damageClock<=0){damagePlayer(e.damage);damageClock=.55;}}}
    for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;for(const e of enemies){if(e.hp>0&&Math.hypot(s.x-e.x,s.y-e.y)<e.r+s.r){e.hp-=s.damage;s.life=0;e.hit=.12;burst(s.x,s.y,'#ffcb71',3);break;}}}shots=shots.filter(s=>s.life>0);
    for(const e of enemies){if(e.hp<=0){kills++;addOrb(e.x,e.y,e.value);if(Math.random()<.13)gameGold++;burst(e.x,e.y,e.color,5);e.dead=true;}e.hit=Math.max(0,e.hit-dt);}enemies=enemies.filter(e=>!e.dead);
    for(const o of orbs){const d=Math.hypot(player.x-o.x,player.y-o.y);if(d<player.magnet+22){const force=d<18?240:Math.max(35,230-d*1.2);o.x+=(player.x-o.x)/(d||1)*force*dt;o.y+=(player.y-o.y)/(d||1)*force*dt;}if(d<player.r+o.r+3){o.got=true;gainXp(o.v);playTone(620,.035);}}orbs=orbs.filter(o=>!o.got);
    for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);
    if(chestClock<0&&elapsed>30){chestClock=55;addOrb(player.x+(Math.random()-.5)*140,player.y+(Math.random()-.5)*130,5);gameGold+=3;showToast('✦ COFRE DEL BOSQUE  +3 ORO');}
  }
  function worldToScreen(x,y){return{x:W/2+(x-player.x),y:H/2+(y-player.y)};}
  function render(){ctx.clearRect(0,0,W,H);drawWorld();drawOrbs();drawShots();drawEnemies();drawPlayer();drawParticles();}
  function drawWorld(){const g=ctx.createRadialGradient(W/2,H/2,20,W/2,H/2,Math.max(W,H)*.78);g.addColorStop(0,'#1d2930');g.addColorStop(.48,'#18232b');g.addColorStop(1,'#111722');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);const ox=((player?.x||0)*.22)%68,oy=((player?.y||0)*.22)%68;ctx.strokeStyle='rgba(115,151,134,.065)';ctx.lineWidth=1;for(let x=-68;x<W+68;x+=68){ctx.beginPath();ctx.moveTo(x-ox,0);ctx.lineTo(x-ox,H);ctx.stroke();}for(let y=-68;y<H+68;y+=68){ctx.beginPath();ctx.moveTo(0,y-oy);ctx.lineTo(W,y-oy);ctx.stroke();}
    for(let i=0;i<decor.length;i++){const d=decor[i],x=(d.x-ox*1.4+W)%W,y=(d.y-oy*1.4+H)%H;ctx.globalAlpha=d.a*(.65+.35*Math.sin(animTime*1.5+d.p));ctx.fillStyle=i%5===0?'#d4b768':'#9db9a4';ctx.beginPath();ctx.arc(x,y,d.r,0,TAU);ctx.fill();}ctx.globalAlpha=1;
    // drifting bramble silhouettes
    for(let i=0;i<10;i++){let x=((i*173+W*.13-ox*1.7)%(W+80)+W+80)%(W+80)-40,y=((i*97+H*.11-oy*1.7)%(H+80)+H+80)%(H+80)-40;ctx.fillStyle='rgba(8,13,20,.36)';ctx.beginPath();ctx.ellipse(x,y,16,6,i*.7,0,TAU);ctx.fill();ctx.strokeStyle='rgba(70,102,91,.15)';ctx.beginPath();ctx.moveTo(x-10,y);ctx.quadraticCurveTo(x,y-11,x+13,y+1);ctx.stroke();}}
  function drawOrbs(){for(const o of orbs){const p=worldToScreen(o.x,o.y);ctx.globalAlpha=.6+.4*Math.sin(animTime*5+o.p);ctx.shadowBlur=12;ctx.shadowColor=o.v>2?'#f4cb70':'#83e3d1';ctx.fillStyle=o.v>2?'#f4cb70':'#8de6d2';ctx.beginPath();ctx.arc(p.x,p.y,o.r,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=1;}}
  function drawShots(){for(const s of shots){const p=worldToScreen(s.x,s.y);ctx.shadowBlur=15;ctx.shadowColor='#65d8e6';ctx.fillStyle='#d5fff1';ctx.beginPath();ctx.arc(p.x,p.y,s.r,0,TAU);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#5ac8d0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-s.vx*.035,p.y-s.vy*.035);ctx.stroke();}}
