    // cloak and hood
    ctx.fillStyle='#26263a';ctx.beginPath();ctx.moveTo(-10,1);ctx.lineTo(-14,12);ctx.lineTo(0,18);ctx.lineTo(14,12);ctx.lineTo(10,1);ctx.closePath();ctx.fill();ctx.fillStyle='#b89a65';ctx.beginPath();ctx.ellipse(0,-5,9,10,0,0,TAU);ctx.fill();ctx.fillStyle='#262339';ctx.beginPath();ctx.arc(0,-7,9,Math.PI,TAU);ctx.lineTo(7,0);ctx.quadraticCurveTo(0,-3,-7,0);ctx.closePath();ctx.fill();ctx.fillStyle='#77e0df';ctx.fillRect(player.face>0?1:-4,-3,3,2);ctx.strokeStyle='#e8ca85';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,11);ctx.lineTo(0,17);ctx.stroke();ctx.restore();}
