  document.getElementById('playBtn').addEventListener('click',begin);document.getElementById('againBtn').addEventListener('click',begin);document.getElementById('resumeBtn').addEventListener('click',togglePause);el('pauseBtn').addEventListener('click',togglePause);el('soundBtn').addEventListener('click',e=>{muted=!muted;e.currentTarget.classList.toggle('muted',muted);e.currentTarget.textContent=muted?'♫':'♪';if(!muted)playTone(600,.08);});
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys[k]=true;if(k==='escape'||k==='p'){if(mode==='playing'||mode==='paused')togglePause();}});window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};if(mode==='playing')togglePause();});
  function joyMove(e){const r=ui.joystick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=29,d=Math.hypot(dx,dy),scale=d>max?max/d:1;joy.x=dx*scale/max;joy.y=dy*scale/max;ui.knob.style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}
  ui.joystick.addEventListener('pointerdown',e=>{e.preventDefault();joy.active=true;ui.joystick.setPointerCapture(e.pointerId);joyMove(e);});ui.joystick.addEventListener('pointermove',e=>{if(joy.active)joyMove(e);});function joyEnd(){joy.active=false;joy.x=joy.y=0;ui.knob.style.transform='translate(0,0)';}ui.joystick.addEventListener('pointerup',joyEnd);ui.joystick.addEventListener('pointercancel',joyEnd);
  el('bankGold').textContent=String(bank).padStart(3,'0');el('bestTime').textContent=formatTime(best);
  // Atmospheric idle scene behind the title; gameplay replaces it when started.
  player=makePlayer();function idle(now){if(mode!=='menu')return;animTime=now/1000;ctx.clearRect(0,0,W,H);drawWorld();const old=player;player.x=Math.sin(animTime*.12)*65;player.y=Math.cos(animTime*.15)*28;drawPlayer();player=old;raf=requestAnimationFrame(idle);}raf=requestAnimationFrame(idle);
})();

